<?php
/** Plugin Name: Instapass Claude Credit Cycle
 * Description: Owner-managed monthly expiry and remaining-time prices for Claude credits only.
 * Version: 1.1.0
 */
defined('ABSPATH')||exit;
function ip_ce_defaults(){return ['enabled'=>true,'start_day'=>1,'tenure_mode'=>'calendar','tenure_days'=>28,'rates'=>[22=>'40.00',15=>'35.00',8=>'30.00',3=>'25.00',1=>'20.00']];}
function ip_ce_config(){ $v=get_option('instapass_claude_credit_cycle',[]);return array_replace(ip_ce_defaults(),is_array($v)?$v:[]); }
function ip_ce_fingerprint(){return hash('sha256',wp_json_encode(ip_ce_config()));}
function ip_ce_now(){if(getenv('INSTAPASS_ISOLATED_TEST')==='yes'&&isset($GLOBALS['ip_ce_test_now']))return (int)$GLOBALS['ip_ce_test_now'];return $GLOBALS['ip_ce_request_time']??=time();}
function ip_ce_boundary($month,$day){return $month->setDate((int)$month->format('Y'),(int)$month->format('m'),min($day,(int)$month->format('t')))->setTime(0,0,0);}
function ip_ce_state($at=null,$config=null){return ip_om_cycle_state($at,$config);}
function ip_ce_claude($p){$o=function_exists('ipl_offer')?ipl_offer($p->get_id()):null;return $o&&$o['group']['key']==='claude-credits';}
function ip_ce_date($timestamp){return wp_date('j M Y',$timestamp);}
function ip_ce_price($value,$p,$field){
 if(!function_exists('instapass_cc_front')||!instapass_cc_front()||!ip_ce_claude($p))return $value;$s=ip_ce_state();if(!$s['enabled']||$s['days']<1)return '';if($value==='')return '';
 $bps=(int)round((float)$s['percent']*100);$currency=instapass_cc_currency();
 if($currency==='PKR'&&$p->get_meta('_instapass_pkr_regular_price')===''){
  $getter=$field==='regular'?'get_regular_price':($field==='sale'?'get_sale_price':'get_price');$raw=instapass_cc_amount($p->{$getter}('edit'),$p,$field,'USD');if($raw==='')return '';$cents=(int)round((float)$raw*100);$scaled=intdiv($cents*$bps+2000,4000);$converted=Instapass_Control_Money::pkr_unit($scaled,instapass_cc_rate());return $cents>0&&$converted===0?'':(string)$converted;
 }
 $cents=(int)round((float)$value*100);$scaled=intdiv($cents*$bps+2000,4000);return $cents>0&&$scaled===0?'':number_format($scaled/100,2,'.','');
}
foreach(['price'=>'price','regular_price'=>'regular','sale_price'=>'sale'] as $hook=>$field)add_filter('woocommerce_product_get_'.$hook,fn($v,$p)=>ip_ce_price($v,$p,$field),200,2);
add_filter('woocommerce_is_purchasable',function($yes,$p){return ip_ce_claude($p)?$yes&&ip_ce_state()['enabled']&&ip_ce_state()['days']>0:$yes;},2500,2);
add_filter('woocommerce_structured_data_product',function($data,$p){if(ip_ce_claude($p)&&(!ip_ce_state()['enabled']||ip_ce_state()['days']<1))unset($data['offers']);return $data;},2500,2);
add_filter('ipl_pending_quote_html',function($html,$p){if(!ip_ce_claude($p)||(ip_ce_state()['enabled']&&ip_ce_state()['days']>0))return $html;return '<div class="ipl-price ipl-pending">Claude credits currently unavailable</div><p class="ipl-term">Please check back for availability.</p><button class="ipl-buy" disabled>Currently unavailable</button>';},10,2);
add_filter('ipl_credit_expiry_label',function($label,$g){return $g['key']==='claude-credits'?'Expires '.ip_ce_date(ip_ce_state()['expiry']):($g['key']==='chatgpt-credits'?ip_om_credit_term_label($g,true):$label);},10,2);
add_filter('ipl_credit_order_expiry',function($label,$g){return $g['key']==='claude-credits'?ip_ce_date(ip_ce_state()['expiry']):($g['key']==='chatgpt-credits'?ip_om_credit_term_label($g,false):$label);},10,2);
add_filter('ipl_credit_price_note',function($html,$p){if(!ip_ce_claude($p))return $html;$s=ip_ce_state();return '<span class="ip-term-upfront ip-credit-cycle-note" data-percent="'.esc_attr($s['percent']).'" data-expiry="'.esc_attr($s['expiry']).'">Current rate: '.esc_html((string)(float)$s['percent']).'% of the credit balance. <a href="'.esc_url(home_url('/faq/#claude-credit-expiry')).'">How expiry pricing works</a></span>';},10,2);
add_filter('woocommerce_cart_hash',function($hash){if(!function_exists('WC')||!WC()->cart)return $hash;foreach(WC()->cart->get_cart() as $i)if(ip_ce_claude($i['data'])){$s=ip_ce_state();return hash('sha256',$hash.'|claude-credit-cycle|'.$s['config_hash'].'|'.$s['start'].'|'.$s['expiry'].'|'.$s['percent']);}return $hash;},2500);
add_action('woocommerce_check_cart_items',function(){if(!WC()->cart||ip_ce_state()['enabled'])return;foreach(WC()->cart->get_cart() as $i)if(ip_ce_claude($i['data'])){wc_add_notice('Claude credit purchases are paused. Remove this item to continue.','error');break;}},2500);
add_action('woocommerce_checkout_create_order_line_item',function($item,$key,$values){if(!isset($values['data'])||!ip_ce_claude($values['data']))return;$s=ip_ce_state();$item->add_meta_data('_instapass_credit_batch_snapshot',['start'=>$s['start'],'expiry'=>$s['expiry'],'remaining_days'=>$s['days'],'percent_of_face'=>$s['percent'],'timezone'=>wp_timezone_string(),'at_utc'=>gmdate('c',ip_ce_now())],true);},45,3);
function ip_ce_validate($in){return ip_om_cycle_validate($in);}
function ip_ce_validate_legacy($in){
 if(!is_array($in)||!is_string($in['start_day']??null)||!preg_match('/^(?:[1-9]|[12][0-9]|3[01])$/D',$in['start_day']))throw new InvalidArgumentException('Choose a monthly start day from 1 to 31.');$v=['enabled'=>!empty($in['enabled']),'start_day'=>(int)$in['start_day'],'rates'=>[]];
 foreach([22,15,8,3,1] as $key){$raw=$in['rates'][$key]??null;if(!is_string($raw)||!preg_match('/^(?:0|[1-9][0-9]?|100)(?:\.[0-9]{1,2})?$/D',$raw)||(float)$raw<=0||(float)$raw>100)throw new InvalidArgumentException('Each rate must be greater than zero and at most 100%.');$v['rates'][$key]=number_format((float)$raw,2,'.','');}
 $last=101;foreach($v['rates'] as $rate){if((float)$rate>$last)throw new InvalidArgumentException('Rates must stay the same or decrease as expiry approaches.');$last=(float)$rate;}return $v;
}
add_action('admin_menu',function(){add_submenu_page('instapass-control','Claude credit pricing','Claude Credit Pricing','manage_woocommerce','instapass-credit-cycle','ip_ce_admin');},45);
function ip_ce_admin(){return ip_om_cycle_admin();}
function ip_ce_admin_legacy(){
 if(!current_user_can('manage_woocommerce'))return;$c=ip_ce_config();$s=ip_ce_state();echo '<div class="wrap"><h1>Claude Credit Pricing</h1><p>Claude credits belong to a monthly batch. Their price falls as expiry approaches. ChatGPT credits keep their separate full-month pricing.</p>';if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Credit cycle settings saved.</p></div>';
 echo '<p><strong>Current batch:</strong> '.esc_html(ip_ce_date($s['start']).' → '.ip_ce_date($s['expiry'])).'<br>About '.absint($s['days']).' days remaining; current rate '.esc_html((string)(float)$s['percent']).'% of face value. Prices renew at the next cycle boundary.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ip_ce_save">';wp_nonce_field('ip_ce_save');echo '<input type="hidden" name="fingerprint" value="'.esc_attr(ip_ce_fingerprint()).'"><table class="form-table"><tr><th>Purchases</th><td><label><input type="checkbox" name="enabled" value="1" '.checked($c['enabled'],true,false).'> Enable Claude credit purchases</label></td></tr><tr><th><label for="ip-ce-start">Monthly start day</label></th><td><input id="ip-ce-start" name="start_day" type="number" min="1" max="31" step="1" value="'.absint($c['start_day']).'" required><p class="description">1 means the first day of every month. For a start day beyond a short month, use that month’s last day. Cycles start at 00:00 in '.esc_html(wp_timezone_string()).'. Change the timezone under WordPress Settings → General.</p></td></tr>';
 foreach(ip_om_rate_labels($c['rates']) as $key=>$label)echo '<tr><th><label for="ip-ce-rate-'.$key.'">'.esc_html($label).' remaining</label></th><td><input id="ip-ce-rate-'.$key.'" name="rates['.$key.']" type="number" min="0.01" max="100" step="0.01" value="'.esc_attr($c['rates'][$key]).'" required> % of the credit balance</td></tr>';
 echo '</table><p>The approved stored base price is 40% of the credit balance. These rates scale that base price, including independent GBP/EUR prices; automatic PKR is converted after this calculation. Existing orders retain the purchased amount and expiry. TOOLKIT5 can apply afterward when the basket qualifies.</p>';submit_button('Save Claude credit pricing');echo '</form></div>';
}
add_action('admin_post_ip_ce_save',function(){if(!current_user_can('manage_woocommerce'))wp_die('Permission denied','',['response'=>403]);check_admin_referer('ip_ce_save');$fp=$_POST['fingerprint']??null;if(!is_string($fp)||!hash_equals(ip_ce_fingerprint(),wp_unslash($fp)))wp_die('Settings changed in another session. Reload before saving.','',['response'=>409]);try{$v=ip_ce_validate(wp_unslash($_POST));}catch(InvalidArgumentException $e){wp_die(esc_html($e->getMessage()),'Invalid credit settings',['response'=>400]);}update_option('instapass_claude_credit_cycle',$v,false);wp_safe_redirect(admin_url('admin.php?page=instapass-credit-cycle&saved=1'));exit;});
add_filter('render_block_core/post-content',function($html){if(!is_page('faq')||str_contains($html,'id="claude-credit-expiry"'))return $html;$c=ip_ce_config();$h='<section id="claude-credit-expiry" style="margin:2rem 0"><h2>How does credit expiry affect the price?</h2><p>Claude Credits share a monthly batch expiry. Buying later does not extend that expiry. The current cycle starts on day '.absint($c['start_day']).' of each month, with short months using their last day when necessary. The exact expiry is shown before purchase. Prices refresh automatically; the number of days is rounded up to the next whole day.</p><ul>';foreach(ip_om_rate_labels($c['rates']) as $key=>$label)$h.='<li>'.esc_html($label.': '.(float)$c['rates'][$key].'% of credit face value').'</li>';return $html.$h.'</ul><p>ChatGPT credit duration and base prices are shown on its product tile. The 5% TOOLKIT5 coupon can reduce a qualifying basket further. Claude credit prices reset when the next monthly batch begins. Existing purchases keep the expiry recorded on their order.</p></section>';},40);
